const workshopEntries = workshopSettings.replace(/^\{\r?\n/, '').replace(/\r?\n\}$/, '');
const checked = '<p class="checked-note">Checked against VS Code Insiders 1.148 and the docs. Not yet tested on a clean personal account.</p>';
