const pause = `<button class="field-pause" type="button" aria-label="Pause the background animation" hidden><svg class="when-playing" viewBox="0 0 16 16" fill="currentColor" aria-hidden="true"><path d="M4 3h3v10H4zm5 0h3v10H9z"/></svg><svg class="when-paused" viewBox="0 0 16 16" fill="currentColor" aria-hidden="true"><path d="m5 2 9 6-9 6z"/></svg></button>`;
