const skolaBuildCommands = prefix => `<p><strong>Windows:</strong> use PowerShell, VS Code's default terminal on Windows:</p>${promptBlock(`${prefix}-powershell`, "$env:BASE_PATH = '/skola/'\nnpx.cmd pnpm@10.28.2 build", 'PowerShell on Windows')}<p class="small muted"><code>npx.cmd</code> avoids a blocked <code>npx.ps1</code> shim without changing execution policy. The environment value lasts for this terminal; close it afterward or restore its earlier value.</p><p><strong>Mac or Linux:</strong></p>${promptBlock(`${prefix}-posix`, 'BASE_PATH=/skola/ npx pnpm@10.28.2 build', 'Mac or Linux shell')}<p><strong>Git Bash on Windows:</strong> it rewrites <code>/skola/</code> into a Windows path unless path conversion is disabled for this command:</p>${promptBlock(`${prefix}-git-bash`, 'MSYS_NO_PATHCONV=1 BASE_PATH=/skola/ npx pnpm@10.28.2 build', 'Git Bash on Windows')}`;
const next = (title, text, path) => `<a class="next-link" href="${u(path)}"><span><strong>${title}</strong><small>${text}</small></span><span aria-hidden="true">↗</span></a>`;

const home = `<section class="hero" aria-labelledby="home-title"><div class="hero-field" data-field="hero" data-field-avoid=".hero-text" aria-hidden="true"></div>${pause}<div class="hero-inner"><div class="hero-text"><p class="eyebrow">With UXPA Seattle</p><h1 id="home-title">AI-First<br>Design<br>Workshop</h1><p class="hero-when"><time datetime="2026-11-19T17:30:00-08:00">Thursday, Nov 19, 2026</time><br>5:30 to 8:30 PM PT · Seattle</p><p class="hero-note">Ship a 2.0 of a real open-source app in one evening. Agents do the heavy lifting while you make the design calls.</p><div class="actions"><a class="button" href="${u('get-ready/')}">Get ready <span aria-hidden="true">↗</span></a><a class="text-link" href="${u('tonight/')}">See tonight's draft guide →</a></div></div></div></section>
<div class="wrap">
<section class="section" aria-labelledby="make"><div class="section-head"><h2 id="make">Skola 2.0 in one evening</h2><p>Your fork of <a href="${DOCS.skola}">Skola</a>, not an official release. The goal is a tested fix, a redesign from your own markup, Listen mode, three directions, a narrated demo and a working site beside your repo.</p></div><div class="capability-grid"><div class="capability"><span class="number">01</span><h3>Fix it and prove it</h3><p>Make Add Card save, with a test that fails before and passes after.</p></div><div class="capability"><span class="number">02</span><h3>Redesign from your markup</h3><p>Use arrows, circles, notes and crop to change the real study screen.</p></div><div class="capability"><span class="number">03</span><h3>Add Listen mode</h3><p>Hear the visible card on demand, while keeping studying usable in silence.</p></div><div class="capability"><span class="number">04</span><h3>Try three directions</h3><p>Compare different Today homes that help you choose what to study.</p></div><div class="capability"><span class="number">05</span><h3>Make a narrated demo</h3><p>Record a short real flow while another independent task runs.</p></div><div class="capability"><span class="number">06</span><h3>Share your fork</h3><p>Leave with a live link and a repo link, crediting Skola and naming your own changes.</p></div></div><p class="small muted" style="margin-top:30px">Draft run sheet. We're rehearsing it, and prompts may change. The practice brief and interview notes are fictional, not the Skola maintainer's roadmap or real customer evidence.</p></section>
<section class="section" aria-labelledby="clock"><div class="section-head"><h2 id="clock">Tonight's clock</h2><p>All times are Pacific. We'll build together first, then make room for your own projects.</p></div><ol class="timeline"><li><time datetime="2026-11-19T17:30:00-08:00">5:30 PM</time><strong>Arrive</strong><small>Check in, food, conversation</small></li><li><time datetime="2026-11-19T17:50:00-08:00">5:50 PM</time><strong>Meet each other</strong><small>Names and what you want to try</small></li><li><time datetime="2026-11-19T18:00:00-08:00">6:00 PM</time><strong>Get oriented</strong><small>The tools and ground rules</small></li><li><time datetime="2026-11-19T18:10:00-08:00">6:10 PM</time><strong>Build together</strong><small>Small tasks, with pauses for help</small></li><li><time datetime="2026-11-19T19:10:00-08:00">7:10 PM</time><strong>Make it yours</strong><small>Free work in pairs</small></li><li><time datetime="2026-11-19T20:00:00-08:00">8:00 PM</time><strong>Show and tell</strong><small>A result and one decision</small></li><li><time datetime="2026-11-19T20:20:00-08:00">8:20 PM</time><strong>Keep going</strong><small>Questions and take-home. End at 8:30.</small></li></ol></section>
<section class="section" aria-labelledby="hosts"><div class="section-head"><h2 id="hosts">Hosted by UXPA Seattle, with Eli King and Thoa Nguyen</h2><p>We're sharing how we work on our own teams. There's no single right way to design with AI.</p></div><div class="hosts"><div class="host"><h3>Eli King</h3><p>A product designer working on AI experiences in VS Code and GitHub Copilot. He prototypes in code and contributes to open source VS Code.</p></div><div class="host"><h3>Thoa Nguyen</h3><p>A product designer working on how developers build AI agents. She experiments in code and builds agents to review her designs.</p></div></div><p class="small muted" style="margin-top:32px">The address is on your Luma ticket. <a href="https://luma.com/hw3533y5">View the event on Luma</a>.</p></section>
<section class="section" aria-labelledby="your-next"><div class="section-head"><h2 id="your-next">Everything for the evening</h2><p>Start with setup. The guide and glossary will be here when you need them.</p></div><div class="next-grid">${next('Get ready', 'The setup, permissions and costs.', 'get-ready/')}${next('Tonight', 'Draft task cards with prompts to copy.', 'tonight/')}${next('Words to know', 'GitHub and AI, in plain words.', 'words/')}${next('Keep going', 'The password-protected take-home.', 'keep-going/')}${next('Skills', 'Reusable workflows for your own projects.', 'skills/')}</div></section>
</div>`;

const ready = hero('Before Thursday', 'Get ready', 'Bring a personal laptop and your charger. Prepare Git, Node LTS and your GitHub sign-in; we will do the workshop settings together.') + layout([
  ['VS Code Insiders', 'insiders'], ['GitHub sign-in', 'github-account'], ['Git', 'git'], ['Node and packages', 'node'], ['Your free month', 'free-month'], ['Spending', 'spending'], ['What is public', 'public'], ['Module 1 settings', 'workshop-settings'], ['Dictation', 'dictation'], ['Screenshot and mark up', 'screenshot-markup'], ['Computer Use', 'computer-use'], ['Mode and permissions', 'permissions'], ['Controls', 'controls'],
], `<div class="note"><p><strong>Prework:</strong> VS Code Insiders, a personal GitHub sign-in, Git and Node LTS. We paste settings together in Module 1.</p><p>Our default is <strong>GPT-6.2 Sol at medium effort</strong> in the Copilot harness. Choose it in the model picker; the settings snippet does not force a model. Credits for the rehearsed modules are still being measured.</p></div>
<section id="insiders"><div class="step-heading"><span class="step-number">01</span><h2>Install VS Code Insiders</h2></div><p>Tonight uses <strong>VS Code Insiders</strong>, not the regular download linked on Luma. Insiders gets new builds frequently. Both versions can live side by side.</p><p><a class="button" href="${DOCS.insiders}">Download Insiders</a></p><p>Choose your operating system, install it, and open it once. Keep your existing editor if you already use one.</p>${detail('Adds a separate app for editing files and working with agents. Opening a folder lets the app read that project; review workspace trust before allowing code to run.', 'Quit Insiders and uninstall the app. Your project files stay where you saved them. Settings and extensions may remain unless you also remove their data.')} ${docs([['Install and download', DOCS.insiders], ['Uninstall VS Code', DOCS.uninstall]])}</section>
<section id="github-account"><div class="step-heading"><span class="step-number">02</span><h2>Sign in to a personal GitHub account</h2></div><p>In Insiders, open the Accounts menu and sign in to GitHub for Copilot. Use a personal account to make your own ${term('fork', 'fork')} of the workshop project. If you need one, <a href="${DOCS.signup}">create a GitHub account</a>.</p><p>Check that the account name is the one you want to use before redeeming your code. Don't choose an additional paid plan during setup.</p>${detail('Connects VS Code to the GitHub account you approve. Copilot requests use that account\'s access and usage allowance.', 'Use the Accounts menu to sign out. This does not cancel a subscription or delete your GitHub account. Manage any plan separately in GitHub settings.')} ${docs([['Set up Copilot in VS Code', DOCS.setup], ['Manage your plan', DOCS.plan]])}</section>
<section id="git"><div class="step-heading"><span class="step-number">03</span><h2>Git for your own fork</h2></div><p>You need a personal GitHub sign-in and Git to work in your own ${term('fork', 'fork')} of Skola. We will make the folder and clone your fork from VS Code on Mac and Windows.</p><h3>Mac</h3><p>In VS Code, open Terminal > New Terminal and check:</p>${promptBlock('git-version', 'git --version', 'Terminal command')}<p>If Git is missing, macOS may offer Command Line Tools. Review that developer-tools download before installing. It includes more than Git.</p><h3>Windows</h3><p>Install <a href="${DOCS.gitWindows}">Git for Windows</a>, review the installer choices, then reopen Insiders and run the same check.</p>${detail('Adds Git, which saves history and clones your repository. macOS Command Line Tools also includes other developer tools; Git for Windows can add Git Bash and shell integration.', 'Windows: remove Git in Settings > Apps > Installed apps. On Mac, do not remove shared developer tools that other apps use. If you installed them only for the workshop, ask for help before removing the package.')}<div class="note"><p><strong>Nothing goes to the original Skola project.</strong> No PRs, issues, comments or stars from the workshop. A fork PR can default to upstream, so check the base repository every time: it must be your own fork.</p></div>${docs([['Install Git', DOCS.git], ['Skola source, read-only reference', DOCS.skola]])}</section>
<section id="node"><div class="step-heading"><span class="step-number">04</span><h2>Node and the project packages</h2></div><p>Install the <strong>current LTS</strong> from <a href="${DOCS.node}">nodejs.org</a>. Node runs the project's development tools; the installer also provides npm and npx. If you already manage Node versions, keep that setup and select its current LTS instead of adding a second installation.</p><ol><li><strong>Mac:</strong> select macOS and the LTS installer (<code>.pkg</code>) on nodejs.org. Run it and review the installer prompts.</li><li><strong>Windows:</strong> select Windows and the LTS installer (<code>.msi</code>). Run it and review the installer prompts.</li><li>Quit and reopen Insiders. In Terminal > New Terminal, check both tools:</li></ol>${promptBlock('node-check', 'node --version\nnpm --version', 'Check Node and npm')}<p class="small muted">Tests, type checks and builds pass on GitHub's Windows, macOS and Linux runners with Node 22 and 26: all six jobs. Personal-laptop UI and permissions still need rehearsal.</p><p>We will use pnpm through <code>npx</code>, not Corepack and not a global pnpm install. Skola pins pnpm <strong>10.28.2</strong>.</p><details><summary>Draft: optional, install before you come</summary><p>The Wi-Fi plan is still open. Once you have your own fork in its project folder, the dependency command is:</p>${promptBlock('skola-install', 'npx pnpm@10.28.2 install --frozen-lockfile', 'Install inside your project folder')}<p>On Windows, use <code>npx.cmd</code> in place of <code>npx</code> if PowerShell blocks its script. No execution-policy change is needed. Review the download before approving it. If install-script warnings appear, ask for help rather than approving everything. Do not start the app until the checked workshop prep has disabled cloud sync.</p></details>${detail('Node and npm are installed on your computer. Budget about 900 MB for Skola\'s pnpm store plus node_modules. npx also caches pnpm, and other caches can use more space.', 'Keep any work you want, then delete only your workshop project folder. Use the cache steps below to remove its npx entry. This does not uninstall Node: on Windows use Installed apps; with a version manager use that manager. A Mac package install has no simple app to drag to the Trash, so do not manually remove a shared runtime without checking what else uses it.')}<p>Cold installs from public npm took about <strong>10 to 36 seconds</strong> on the runners. They have fast networks; venue Wi-Fi will be slower.</p><details id="skola-build"><summary>Build your prepared fork at the Pages path</summary>${skolaBuildCommands('setup-build')}<p class="small muted">These commands are for the checked workshop prep. They do not publish or deploy the app. <a href="${DOCS.skolaCI}">See the six passing runner jobs</a>.</p></details><h3>Clear the workshop's npx cache</h3><p>List the entries, inspect the one used for pnpm, then remove only that entry. Replace <code>CACHE_KEY</code> with the key shown by the list:</p>${promptBlock('npx-cache', 'npm cache npx ls\nnpm cache npx info CACHE_KEY\nnpm cache npx rm CACHE_KEY', 'Review and remove the npx entry')}<p class="small muted">These are npm's npx-cache commands, not a command to delete your whole npm cache. If your npm version does not support them, use its matching docs or ask for help. Do not clear unrelated entries by guesswork.</p>${docs([['Node LTS download', DOCS.node], ['Node and npm installation', DOCS.nodeInstall], ['npx cache commands', DOCS.npmCache]])}</section>
<section id="free-month"><div class="step-heading"><h2>Your free month of GitHub Copilot Max</h2></div><p>Every attendee gets a <strong>free month of GitHub Copilot Max</strong>. We'll help you redeem your personal code at check-in. Keep your code private.</p><div class="note"><p><strong>Redemption details are coming.</strong> The code entry steps, any card requirement, renewal date and cancellation steps for this offer still need confirmation. We'll check them with you before you accept the offer.</p></div><p>GitHub's standard Max plan currently costs <strong>$100 USD a month</strong> and includes <strong>20,000 AI credits</strong>. One credit is one cent. The total includes a variable flex allotment; check the current terms when you redeem.</p>${detail('Redeeming the offer changes Copilot access on the account you choose. Read the actual offer terms before confirming.', 'Use GitHub\'s plan settings to manage or cancel a plan. The exact cancellation route and renewal terms for these promotional codes are still being confirmed. Uninstalling VS Code is not a cancellation.')} ${docs([['Max pricing and credits', DOCS.billing], ['Plan and cancellation settings', DOCS.plan]])}</section>
<section id="spending"><h2>Keep spending a choice</h2><p>The workshop files are free. AI requests use your account's credits. Input, output, cached input and cache writes can all count; parallel sessions, retries and scheduled runs can use more.</p><ol><li>On GitHub, open <strong>Settings > Billing &amp; licensing > Budgets and alerts</strong>.</li><li>Review a <strong>Bundled AI credits</strong> budget of <strong>$0</strong>, with <strong>Stop usage when budget limit is reached</strong> selected if you do not want paid AI-credit overage. An alert alone does not stop usage.</li><li>Check your usage in Billing &amp; licensing. Open <strong>Licensing</strong> to review your plan and renewal date. The workshop code's redemption, card and renewal terms are still being confirmed.</li></ol><div class="note"><p>That budget does not cancel a subscription renewal, cover provider API-key bills or cap separate Cloud compute, memory and storage. Check those separately before any Cloud work. Keep workshop requests routed through Copilot; you do not need your own provider key.</p></div><p>Stop work and review budgets if you reach your intended limit. Reducing a budget or canceling a plan does not erase charges already incurred. Enabling the two settings costs nothing by itself; sending or scheduling work can use credits.</p>${docs([['Manage budgets', DOCS.budget], ['View usage', DOCS.usage], ['Plan and renewal', DOCS.plan], ['Separate Cloud billing', DOCS.cloudBilling]])}</section>
<section id="public"><h2>GitHub Pages is public</h2><p>Publishing a ${term('github-pages', 'GitHub Pages')} site exposes its content to the internet. On a personal GitHub Free account, the repository used for Pages must also be public.</p><p>Before you publish, check the files, screenshots and history for names, personal information, client work, keys and private links. Deleting a file afterward does not remove copies other people may have saved.</p><p>You can unpublish Pages in the repository settings, but that cannot recall shared copies. Nothing in tonight's draft guide publishes automatically.</p>${docs([['Create a GitHub Pages site', DOCS.pages]])}</section>
<section id="workshop-settings"><div class="step-heading"><h2>Module 1: workshop settings</h2></div>${checked}<p>We paste these together in Module 1, not as required prework. The two experimental settings offer Computer Use and Send Later where your account and policies allow them. They do not approve tools, start an automation or purchase anything. Install Insiders below if you haven't yet, then return here.</p><p>Use a backed-up merge in your <strong>Default Profile</strong>. Read the steps below before pasting; do not replace your whole settings file.</p>${promptBlock('workshop-settings-entries', workshopEntries, 'Entries for existing settings')}<p class="small muted">Copy the entries above into your existing outer braces. For a blank file or <code>{}</code>, use the complete snippet below. <a href="${u('get-ready/workshop-settings.jsonc')}" download>Download the settings file</a>.</p><details><summary>Complete snippet for an empty settings file</summary>${promptBlock('workshop-settings-complete', workshopSettings, 'Complete settings snippet')}</details><h3>Add them without losing your settings</h3><ol><li>Open the Command Palette: <strong>Shift+Command+P</strong> on Mac or <strong>Ctrl+Shift+P</strong> on Windows. Run <strong>Profiles: Switch Profile</strong>, note your current profile, then choose <strong>Default</strong>.</li><li>Run <strong>Preferences: Open User Settings (JSON)</strong>. Choose the user file, not Default Settings or Workspace Settings.</li><li>Save a complete local backup as <code>workshop-settings-before.txt</code>, outside your repo. Don't share it; settings can contain private information.</li><li>Paste the two entries inside the existing outer <code>{ }</code>. Put a comma after the preceding entry if it doesn't already have one. Keep the comma between the two new entries. Don't add another pair of braces.</li><li>If a key already exists, change its value to <code>true</code> instead of adding it twice. Note its previous value, or that it was absent.</li><li>Save with <strong>Command+S</strong> or <strong>Ctrl+S</strong>. Resolve any settings warning, save your work, then quit and reopen Insiders for Computer Use.</li></ol><p class="small muted">A separate profile is not the undo route: the Agents window uses the Default Profile, while plugin access, saved automations and OS permissions need their own cleanup.</p><h3 id="undo-setup">Undo it</h3><ol><li>Stop workshop runs. Cancel pending Send Later requests in <strong>Automations</strong>, then disable or delete the workshop automation. Turning off a setting does not cancel accepted schedules.</li><li>Run <code>/computer off</code>, restore its previous setting value, and restart Insiders.</li><li>Revoke the related OS permissions if you no longer want access.</li><li>In the same Default Profile user file, restore each value you changed. Delete only entries that were absent before and fix adjacent commas. Restore the whole backup only if no later edits would be lost.</li><li>In <strong>Customizations > Plugins</strong>, remove the workshop plugin if you don't want it. Keep your earlier plugins and sources.</li></ol>${docs([['User settings', DOCS.settingsGuide], ['Agents-window configuration', DOCS.agentsConfiguration], ['Manage automations', DOCS.automations]])}</section>
<section id="dictation"><div class="step-heading"><h2>Try dictation once</h2></div><p>On an Apple silicon Mac or Windows x64 or Arm64 laptop, select the microphone in the chat input. First use downloads an on-device speech model and asks for microphone access.</p><p>Say: <em>Make the heading a little smaller.</em> Stop the microphone and check the text. ${term('dictation', 'Dictation')} does not send the prompt until you choose to send it. You can delete this test text.</p><p>Audio recognition runs on-device by default on these desktop systems. Optional transcript cleanup sends the text to a model. Turn off optional transcript cleanup in Settings if you don't want that. Intel Mac? Typing is fine; you don't need an extra voice extension for tonight.</p>${detail('Downloads a speech-recognition model and gives VS Code microphone access. Model-based transcript cleanup is a separate setting from on-device audio recognition.', 'Stop dictation, turn off built-in dictation in Settings, and revoke VS Code microphone access in your system privacy settings if you no longer want it. Disabling dictation does not delete the downloaded model.')} ${docs([['Dictation, privacy and supported platforms', DOCS.voice]])}</section>
<section id="screenshot-markup"><h2>Screenshot and mark up</h2>${checked}<p>Try native <strong>Mark Up</strong> in the chat input first. You make the visual mockup; the agent changes the real interface from that image.</p><ol><li>Capture the real interface. Where offered, use <strong>Add Context (+) > Screenshot Window</strong> or <strong>Screenshot App Window...</strong>. You can also use the OS tools below.</li><li>Attach the image to the current chat input: paste with <strong>Command+V</strong> on Mac or <strong>Ctrl+V</strong> on Windows, drop the file, or use <strong>Add Context (+) > Files</strong>. Confirm its thumbnail appears.</li><li>Select the <strong>unsent image</strong>, then <strong>Mark Up</strong>. Use arrows, drawing, text or crop to show your change.</li><li>Select <strong>Done</strong>, then send the image with your request. Ask the agent to change the actual code and inspect the working result.</li></ol><p class="small muted"><strong>Escape applies and finishes markup; it does not discard it.</strong> Select / Move handles added annotations, not the original screenshot's pixels. A cut-and-rearrange workflow still needs checking. Use PNG or JPEG with a model that supports images, and keep private information out.</p><details><summary>If native capture or Mark Up is missing</summary><p><strong>macOS:</strong> use Shift-Command-5 or Shift-Command-4, then edit the thumbnail or open the image in Preview's Markup toolbar. Use SDR / PNG where the format choice is offered.</p><p><strong>Windows:</strong> open Snipping Tool or press Windows logo key + Shift + S. Use its pen, highlighter, shapes and crop. Copy the edited snip with Ctrl+C or save with Ctrl+S.</p><p>Keep an original copy. Paste or attach the edited image, not just its filename. These fallback tools annotate and crop; a layered rearrangement of the original UI is not a checked workshop step.</p></details>${detail('Adds an image to your prompt. Native app-window capture can request screen-recording permission; it does not activate Computer Use or grant app control.', 'Undo marks before finishing, or remove the unsent attachment and attach the original again. Delete only image copies you made. Revoke capture permission separately if you no longer want it.')} ${docs([['Attach images and browser context', DOCS.context], ['Screenshots on Mac', DOCS.macScreenshot], ['Markup in Preview', DOCS.macMarkup], ['Snipping Tool on Windows', DOCS.windowsScreenshot]])}</section>
<section id="computer-use"><h2>Start and stop Computer Use</h2>${checked}<ol><li>After applying the settings and restarting, open a <strong>Copilot</strong> chat on <strong>This Computer</strong>.</li><li>Enter <code>/computer on</code>. First use downloads its plugin. On Mac, choose <strong>Set Up Computer Use</strong> and grant <strong>Accessibility</strong> and <strong>Screen Recording</strong> yourself. Recent macOS versions call the latter <strong>Screen &amp; System Audio Recording</strong>.</li><li>Use only the agreed harmless app task and public practice files. Check each access request.</li><li>Enter <code>/computer off</code> to turn it off. Restore the old setting and restart if you no longer want the feature. Remove its OS grants in <strong>System Settings > Privacy &amp; Security</strong> too.</li></ol><p>Computer Use can inspect and interact with desktop apps. Activation persists across chats and also affects Copilot CLI on that computer. Removing the setting alone does not revoke OS access. Windows has its own setup flow and still needs a first-use rehearsal.</p><p><strong>Screenshot markup is not Computer Use.</strong> You draw the mockup yourself. We may install one small tool together in the room; we'll explain the download, permissions and undo steps before you approve it.</p>${docs([['Computer Use setup and off steps', DOCS.computer], ['Computer Use permissions', DOCS.computerPermissions]])}</section>
<section id="permissions"><h2>Mode and permissions</h2>${checked}<p><strong>Interactive</strong>, <strong>Plan</strong> and <strong>Autopilot</strong> are modes in Copilot. Interactive does the task. Plan proposes an approach first; enter <code>/plan</code> and review it. Autopilot keeps working and <strong>auto-approves tools</strong>.</p><p><strong>Manual</strong>, <strong>Assisted</strong> and <strong>Allow all</strong> are permission levels. Manual follows your existing approval rules, so it does not ask before every action. Assisted uses a model to assess calls and asks about those it does not approve. Allow all runs tools without confirmation.</p><p><strong>New Worktree sessions always use Allow all.</strong> A worktree separates files, not access to your machine. None of these modes or levels is a sandbox.</p><p>Start in a regular folder with Manual permissions and use Allow Once where offered. Only choose broader access deliberately. The settings snippet does not choose it for you.</p>${docs([['Approvals and permissions', DOCS.permissions], ['Planning', DOCS.planning]])}</section>
<section id="controls"><h2>Basic controls</h2>${checked}<p>Use the labeled menu choices first. These shortcuts assume default bindings and the current <strong>steer</strong> preference. Your existing settings can differ.</p><dl class="control-list"><div><dt>Send</dt><dd>Starts an idle request. <span>Mac and Windows: Enter.</span></dd></div><div><dt>Add to Queue</dt><dd>Waits until the current response finishes. <span>Mac: Option+Enter. Windows: Alt+Enter, with the steer default.</span></dd></div><div><dt>Steer with Message</dt><dd>Redirects after the current tool finishes. <span>Mac and Windows: Enter, with the steer default.</span></dd></div><div><dt>Stop and Send</dt><dd>Cancels the request and immediately sends your new message. <span>Use the Send dropdown; no dedicated shortcut confirmed.</span></dd></div><div><dt>Stop</dt><dd>Requests cancellation without another message. <span>Mac: Control+Escape. Windows: Alt+Backspace.</span></dd></div><div><dt>Send Later</dt><dd>Schedules one prompt, not a recurring task. <span>Use Send Later... in the Send dropdown or Chat: Send Later... in the palette. No dedicated shortcut.</span></dd></div><div><dt>Edit and resend</dt><dd>Edits an earlier request. Review what will be rewound first; it does not undo external actions. <span>Enter on a focused request, then Enter to resend, on either platform.</span></dd></div><div><dt>Attach a screenshot</dt><dd>Paste the image, drop a file, or use + > Files. Confirm the thumbnail is supported. <span>Mac: Command+V. Windows: Ctrl+V.</span></dd></div><div><dt>Mark Up</dt><dd>Select the unsent image, choose Mark Up, then Done. <span>Enter opens a focused image. Escape applies and finishes markup, not discard.</span></dd></div><div><dt>Switch model</dt><dd>Use the input's model picker. It changes the next request, not the harness. <span>Mac: Command+Option+period. Windows: Ctrl+Alt+period.</span></dd></div><div><dt>Plan</dt><dd>Enter /plan with the outcome, then review the plan. <span>Mac: Command+period opens the agent picker. Windows: Ctrl+period.</span></dd></div></dl><p class="small muted">If your default is queue, Enter and Option/Alt+Enter swap meanings. Stop does not undo completed actions or cancel every pending follow-up; inspect those separately.</p><details><summary>Before using Send Later</summary><p>Choose a delay or a date and time, and check this device's time zone. A preset schedules immediately. Local Send Later needs an awake computer and an available host; it does not wake your laptop.</p><p>Use Cancel Schedule and confirm the pending entry is gone, or manage it in Automations. Turning off the setting does not cancel accepted requests. If you're unsure a schedule was created, check before retrying. Scheduled runs can use credits and act later with the session's permissions.</p></details>${docs([['Queue, steer and stop', DOCS.chat], ['Review and edit requests', DOCS.review], ['Model picker', DOCS.models], ['Automation requirements', DOCS.automations]])}</section>
`);

